// themes/theme-vars.less

.theme-dark() {
  @color-primary:          #00b4ff;
  @color-primary-alpha:    rgba(0,180,255,0.35);
  @color-success:          rgba(80,200,120,0.6);
  @color-success-solid:    #50c878;
  @color-danger:           #f53f3f;
  @color-text-base:        rgba(255,255,255,0.8);
  @color-text-muted:       rgba(255,255,255,0.5);
  @color-bg-base:          #0d1b2e;
  @color-bg-card:          #0a1628;
  @color-tab-active-bg:    rgba(0,180,255,0.15);
  @color-tab-active-text:  #ffffff;
  @color-tab-default-text: rgba(255,255,255,0.5);
  @color-badge-bg:         #f53f3f;
  @color-warning-line:     #f53f3f;
  @color-border:           rgba(0,180,255,0.25);
  @font-size-base:         14px;
  @font-size-small:        12px;
  @border-radius-base:     4px;
}

.theme-light() {
  @color-primary:          #0090cc;
  @color-primary-alpha:    rgba(0,144,204,0.15);
  @color-success:          rgba(60,180,100,0.6);
  @color-success-solid:    #3cb464;
  @color-danger:           #d93025;
  @color-text-base:        #1a2b3c;
  @color-text-muted:       rgba(26,43,60,0.5);
  @color-bg-base:          #edf4fb;
  @color-bg-card:          #ffffff;
  @color-tab-active-bg:    rgba(0,144,204,0.1);
  @color-tab-active-text:  #0090cc;
  @color-tab-default-text: rgba(26,43,60,0.5);
  @color-badge-bg:         #d93025;
  @color-warning-line:     #d93025;
  @color-border:           rgba(0,144,204,0.2);
  @font-size-base:         14px;
  @font-size-small:        12px;
  @border-radius-base:     4px;
}

// 全局默认兜底（浅色）
.theme-light();
